/* ============ locales.js — the player's language (loaded before anything else) ============
 * The game is written in English. The language is the one chosen in the game
 * (localStorage 'pl.lang'); otherwise the browser's; otherwise English.
 *
 * Every other language downloads only its own dictionary, js/lang/<lang>.js
 * (generated by tools/build_langs.js from js/i18n/<lang>/*.js), here and
 * before the game scripts, so it is ready when they run. If it fails to
 * arrive the game simply shows English. The ?v= fingerprint of this script
 * (added by tools/build.js) is passed on to the dictionary.
 */
window.PL_LOCALES = (() => {
  // [id, name in its own language, Intl locale]
  const choices = [
    ['en', 'English', 'en-GB'], ['es', 'Español', 'es-ES'],
    ['fr', 'Français', 'fr-FR'], ['it', 'Italiano', 'it-IT'],
    ['pt-BR', 'Português (Brasil)', 'pt-BR'],
    ['zh-Hans', '简体中文', 'zh-CN'], ['zh-Hant', '繁體中文', 'zh-TW']
  ];
  function normalize(value) {
    const s = String(value || '').toLowerCase().replace(/_/g, '-');
    if (/^zh(?:-|$)/.test(s)) {
      if (s.includes('-hans')) return 'zh-Hans';
      if (s.includes('-hant') || /^zh-(tw|hk|mo)(-|$)/.test(s)) return 'zh-Hant';
      return 'zh-Hans';
    }
    if (/^pt(?:-|$)/.test(s)) return 'pt-BR';
    const hit = choices.find(([id]) => s === id.toLowerCase() || s.startsWith(id.toLowerCase() + '-'));
    return hit ? hit[0] : null;
  }
  let saved = null;
  try { saved = localStorage.getItem('pl.lang'); } catch (e) { /* storage can be blocked */ }
  const nav = typeof navigator !== 'undefined' ? ((navigator.languages && navigator.languages[0]) || navigator.language) : '';
  const lang = normalize(saved) || normalize(nav) || 'en';
  if (typeof document !== 'undefined' && document.documentElement) document.documentElement.lang = lang;
  if (lang !== 'en' && typeof document !== 'undefined' && document.write) {
    const me = document.currentScript, v = me && /[?&]v=([\w-]+)/.exec(me.src);
    // While the page is still being parsed: runs before the (deferred) game scripts.
    document.write(`<script src="js/lang/${lang}.js${v ? '?v=' + v[1] : ''}"><\/script>`);
  }
  return { choices, normalize, lang, locale: choices.find(([id]) => id === lang)[2] };
})();
